// Verifies X-Hydra-Signature: t=<unix>,v1=<hex HMAC-SHA256 of "<t>.<raw body>"> with HYDRA_WEBHOOK_SECRET.
// Rejects bad or missing signatures and anything older than 5 minutes (replay).
const crypto = require('crypto');
const secret = $env.HYDRA_WEBHOOK_SECRET;
const item = $input.first();
const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const header = String(item.json.headers['x-hydra-signature'] || '');
const m = /^t=(\d+),v1=([0-9a-f]{64})$/.exec(header);
let valid = false;
if (m && secret) {
  const expected = crypto.createHmac('sha256', secret).update(`${m[1]}.${raw}`).digest('hex');
  const fresh = Math.abs(Date.now() / 1000 - Number(m[1])) < 300;
  valid = fresh && crypto.timingSafeEqual(Buffer.from(expected, 'hex'), Buffer.from(m[2], 'hex'));
}
return [{ json: { valid, event: valid ? JSON.parse(raw) : null } }];

// One item per WhatsApp message: an alert to each host number, plus the guest's template where one applies.
// Template names and parameter order must match the templates approved in WhatsApp Manager (see n8n/README.md).
const e = $('Verify signature').first().json.event;
const b = e.booking;
const when = new Date(b.starts_at).toLocaleString('en-IN', { timeZone: 'Asia/Kolkata', weekday: 'short', day: 'numeric', month: 'short', hour: 'numeric', minute: '2-digit' });
const kind = e.type.replace('booking.', '');
const hostLines = {
  created: `NEW ${b.ref}: ${b.name}, ${b.guests} pax, table ${b.table} (${b.zone}), ${when}. ${b.phone_e164}. Notes: ${b.notes || '-'}. Confirm in admin.`,
  confirmed: `CONFIRMED ${b.ref}: ${b.name}, table ${b.table}, ${when}.`,
  cancelled: `CANCELLED by ${b.cancelled_by || 'staff'} ${b.ref}: ${b.name}, table ${b.table}, ${when}. Table is free again.`,
  no_show: `NO-SHOW ${b.ref}: ${b.name}, table ${b.table}, ${when}.`,
  completed: `COMPLETED ${b.ref}: ${b.name}, table ${b.table}.`,
};
const hostText = hostLines[kind] || `${e.type} ${b.ref}`;
const guestTemplate = { created: 'hydra_booking_received', confirmed: 'hydra_booking_confirmed', cancelled: 'hydra_booking_cancelled' }[kind];
const digits = (n) => String(n).replace(/[^0-9]/g, '');
const template = (to, name, params) => ({
  messaging_product: 'whatsapp', to: digits(to), type: 'template',
  template: { name, language: { code: 'en' }, components: [{ type: 'body', parameters: params.map((text) => ({ type: 'text', text: String(text) })) }] },
});
const items = [];
for (const host of String($env.HOST_WHATSAPP_NUMBERS || '').split(',').map((s) => s.trim()).filter(Boolean)) {
  items.push({ json: { audience: 'host', wa: template(host, 'hydra_host_alert', [hostText]), fallbackText: hostText } });
}
if (guestTemplate) {
  items.push({ json: { audience: 'guest', wa: template(b.phone_e164, guestTemplate, [b.name, b.ref, when, b.table, b.guests]), fallbackText: `Could not WhatsApp the guest for ${b.ref} (${b.name}, ${b.phone_e164}). Please call them. ${hostText}` } });
}
if (items.length === 0) items.push({ json: { audience: 'none', wa: null, fallbackText: `No WhatsApp host numbers set. ${hostText}` } });
return items;
